#include <iostream>
#include <type_traits>

template<typename T>
struct TypeBehavior {
    static void info() {
        std::cout << "Generic type" << std::endl;
    }
};

// Specialization for integral types
template<typename T>
struct TypeBehavior<T, typename std::enable_if<std::is_integral<T>::value>::type> {
    static void info() {
        std::cout << "Integral type" << std::endl;
    }
};

// Specialization for floating-point types
template<typename T>
struct TypeBehavior<T, typename std::enable_if<std::is_floating_point<T>::value>::type> {
    static void info() {
        std::cout << "Floating-point type" << std::endl;
    }
};

int main() {
    TypeBehavior<int>::info(); // Outputs: Integral type
    TypeBehavior<double>::info(); // Outputs: Floating-point type
    TypeBehavior<std::string>::info(); // Outputs: Generic type
    return 0;
}
